import{_ as a,o,c as r,ag as s}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{},"headers":[],"relativePath":"es/faq.md","filePath":"es/faq.md"}'),d={name:"es/faq.md"};function c(n,e,t,i,l,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><h2 id="la-consola-dice-you-lack-the-required-entitlement" tabindex="-1">La consola dice <code>You lack the required entitlement</code> <a class="header-anchor" href="#la-consola-dice-you-lack-the-required-entitlement" aria-label="Permalink to &quot;La consola dice `You lack the required entitlement`&quot;">​</a></h2><p>El script no está vinculado a la cuenta Cfx.re propietaria de la clave de licencia de tu servidor. Comprueba en <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> que la cuenta que compró el script es la que creó la clave de <code>sv_licenseKey</code>. Los derechos (entitlements) se leen al arrancar el servidor: después de una compra nueva reinicia el servidor entero, un <code>restart</code> del recurso no basta.</p><h2 id="could-not-find-dependency-nay-lib-for-resource-nay-car-wash" tabindex="-1"><code>Could not find dependency nay_lib for resource nay_car_wash</code> <a class="header-anchor" href="#could-not-find-dependency-nay-lib-for-resource-nay-car-wash" aria-label="Permalink to &quot;`Could not find dependency nay_lib for resource nay_car_wash`&quot;">​</a></h2><p><code>nay_lib</code> debe iniciarse antes que cualquier script Nayretis, y las dos carpetas deben estar en tu carpeta <code>resources</code>. Revisa el orden de las líneas <code>ensure</code> en <code>server.cfg</code>: <code>ensure nay_lib</code> va primero, después de los recursos de tu framework, inventario y target.</p><h2 id="no-supported-framework-detected" tabindex="-1"><code>No supported framework detected</code> <a class="header-anchor" href="#no-supported-framework-detected" aria-label="Permalink to &quot;`No supported framework detected`&quot;">​</a></h2><p>Inicia <code>nay_lib</code> después del recurso de tu framework. Si la detección sigue fallando, fuérzala en <code>server.cfg</code>, por ejemplo <code>setr nay:framework &quot;esx&quot;</code>. Los valores se indican en la página <a href="/es/bridge/">Bridge</a>. ¿Usas un framework que no es compatible? Escribe un <a href="/es/bridge/custom">adaptador personalizado</a>.</p><h2 id="errores-de-base-de-datos-al-arrancar" tabindex="-1">Errores de base de datos al arrancar <a class="header-anchor" href="#errores-de-base-de-datos-al-arrancar" aria-label="Permalink to &quot;Errores de base de datos al arrancar&quot;">​</a></h2><p><code>oxmysql</code> debe iniciarse antes que <code>nay_lib</code> y estar conectado a tu base de datos (<code>mysql_connection_string</code> en <code>server.cfg</code>). Las tablas se crean en el primer arranque, así que el usuario de la base de datos necesita permiso para crear tablas.</p><h2 id="¿como-cambio-el-idioma" tabindex="-1">¿Cómo cambio el idioma? <a class="header-anchor" href="#¿como-cambio-el-idioma" aria-label="Permalink to &quot;¿Cómo cambio el idioma?&quot;">​</a></h2><p>Abre <code>/nay</code>, luego <strong>Nayretis</strong> y luego <strong>Idioma</strong>. Se incluyen inglés, francés, español, portugués, polaco y alemán, y el idioma se aplica a todos los scripts Nayretis. <code>setr nay:locale &quot;fr&quot;</code> en <code>server.cfg</code> fija el idioma usado hasta que alguien lo cambie en el juego.</p><h2 id="¿que-archivos-puedo-editar" tabindex="-1">¿Qué archivos puedo editar? <a class="header-anchor" href="#¿que-archivos-puedo-editar" aria-label="Permalink to &quot;¿Qué archivos puedo editar?&quot;">​</a></h2><ul><li><code>config.lua</code> de cada script: valores iniciales opcionales. Se aplican hasta que se cambia un ajuste en <code>/nay</code>, y <strong>Restablecer</strong> vuelve a ellos.</li><li><code>locales/*.json</code>: todos los textos que ven los jugadores.</li><li><code>nay_lib/bridge/custom.lua</code>: tu propio adaptador de framework.</li></ul><p>El resto del código está protegido por el escrow de Cfx.</p><h2 id="¿nay-lib-se-conecta-a-algo" tabindex="-1">¿nay_lib se conecta a algo? <a class="header-anchor" href="#¿nay-lib-se-conecta-a-algo" aria-label="Permalink to &quot;¿nay_lib se conecta a algo?&quot;">​</a></h2><p>Al arrancar, <code>nay_lib</code> lee un archivo público de versiones (<code>https://versions.nayretis.com/versions.json</code>) y avisa en la consola cuando hay una actualización disponible. Desactívalo con <code>set nay:versionCheck false</code>. Nada más sale de tu servidor salvo que actives la <a href="/es/nay-lib/api">API HTTP</a> o añadas <a href="/es/nay-lib/webhooks">webhooks</a>.</p><h2 id="¿donde-consigo-ayuda" tabindex="-1">¿Dónde consigo ayuda? <a class="header-anchor" href="#¿donde-consigo-ayuda" aria-label="Permalink to &quot;¿Dónde consigo ayuda?&quot;">​</a></h2><p>Abre un post en <code>#support</code> en el <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discord de Nayretis</a>, un post por problema, con el script y su versión, tu framework, inventario y target, y los errores de la consola del servidor y de F8.</p>',18)])])}const b=a(d,[["render",c]]);export{h as __pageData,b as default};
